SELECT a.create_time, a.update_time, a.id, a.process_id 'process.id', a.product_id, a.task_type_enum, a.quantity, a.inspection_quantity, a.report_type, mba.serial_number serial_number, cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.id 'monomer.id', pm.`name` 'monomer.name', pd.id 'area.id', pd.`name` 'area.name', mbw.id 'workshop.id', mbw.`name` 'workshop.name', mbpl.id 'production_line.id', mbpl.`name` 'production_line.name', mbp.NAME 'process.name', su.id 'user.id', su.name 'user.name', gro.id 'groups.id', gro.name 'groups.name'
,mba.name productName
FROM mes_enclosure_produce_team_report a LEFT JOIN mes_enclosure_task task ON a.task_id = task.id LEFT JOIN contract_project cp ON cp.id = task.project_id LEFT JOIN plan_monomer pm ON pm.id = task.monomer_id LEFT JOIN plan_area pd ON pd.id = task.plan_id LEFT JOIN mes_enclosure_factory mbf ON mbf.id = task.factory_id LEFT JOIN mes_enclosure_workshop mbw ON mbw.id = task.workshop_id LEFT JOIN mes_enclosure_production_line mbpl ON mbpl.id = task.production_line_id LEFT JOIN mes_enclosure_process mbp ON mbp.id = a.process_id LEFT JOIN mes_enclosure_groups gro ON gro.id = task.groups_id LEFT JOIN sys_user su ON a.user_id =su.id
LEFT JOIN tech_machine_part mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_enclosure mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_assemble mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE
a.bool_delete_enum=FALSE
AND DATE(a.create_time) = date(#{date})
mba.serial_number like CONCAT('%',#{serialNumber},'%')
AND a.product_id = #{productId}
AND a.report_ype = #{reportType}
AND a.task_type_enum &#{taskTypeEnum}
AND a.team_id =#{teamId}
AND a.task_id = #{taskId}
AND cp.id = #{projectId}
AND pm.id = #{monomerId}
AND pd.id = #{planId}
AND mbw.id = #{workshopId}
AND mbpl.id = #{productLineId}
AND mbf.id = #{factoryId}

SELECT SUM( a.inspection_quantity ) complete_quantity, SUM( a.price ) price, a.process_name, a.team_id, c.`name` leader_name, a.factory_id 'factory.id', a.production_line_id 'production_line.id', a.workshop_id 'workshop.id', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', a.production_line_name 'production_line.name', SUM(a.mate) mate FROM ( SELECT a.inspection_quantity, a.wage, a.price, a.product_id, a.product_type, a.create_time, mbp.`name` process_name, a.team_id, a.process_id, team.factory_id, team.workshop_id, mbpl.id production_line_id, mbpl.NAME production_line_name, mbt.project_id,
(SELECT net_weight FROM tech_machine_part WHERE id=a.product_id) *a.inspection_quantity/1000
(SELECT net_weight FROM tech_artifact WHERE id=a.product_id) *a.inspection_quantity/1000
(SELECT length FROM tech_enclosure WHERE id=a.product_id) *a.inspection_quantity/1000
( SELECT length FROM tech_assemble WHERE id = a.product_id ) * a.inspection_quantity/1000 mate FROM mes_enclosure_produce_team_report a LEFT JOIN mes_enclosure_task mbt ON a.task_id = mbt.id LEFT JOIN mes_enclosure_process mbp ON mbp.id = a.process_id LEFT JOIN mes_enclosure_team team ON a.team_id = team.id LEFT JOIN mes_enclosure_production_line mbpl ON mbpl.id = team.production_line_id
a.product_type=#{productType} AND team.organization_type = 1
and mbt.project_id=#{projectId}
and team.factory_id=#{factoryId}
and team.production_line_id=#{productionLineId}
and team.workshop_id=#{workshopId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
) AS a LEFT JOIN mes_enclosure_team_user_link b ON a.team_id = b.team_id AND b.bool_delete_enum = FALSE AND b.bool_leader_enum = TRUE LEFT JOIN sys_user c ON b.user_id = c.id LEFT JOIN mes_enclosure_factory mbf ON mbf.id = a.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_enclosure_workshop mbw ON mbw.id = a.workshop_id AND mbw.bool_delete_enum =FALSE GROUP BY a.process_name, a.team_id, c.`name`, a.factory_id , a.production_line_id , a.workshop_id , mbf.`name` , mbw.`name` , a.production_line_name

SELECT a.process_id, mbp.`name` process_name, SUM(a.price) price FROM mes_enclosure_produce_team_report a LEFT JOIN mes_enclosure_team team ON a.team_id = team_id LEFT JOIN mes_enclosure_task mbt ON mbt.id=a.task_id LEFT JOIN mes_enclosure_process mbp ON mbp.id=a.process_id
a.product_type=#{productType} and team.organization_type=1
and team.factory_id=#{factoryId}
and a.team_id=#{teamId}
and team.production_line_id=#{productionLineId}
and team.workshop_id=#{workshopId}
AND DATE(a.create_time)>=DATE(#{startDate})
AND DATE(a.create_time)<=DATE(#{endDate})
GROUP BY process_id

SELECT SUM(a.price) price FROM mes_enclosure_produce_team_report a LEFT JOIN mes_enclosure_team team ON a.team_id = team_id LEFT JOIN mes_enclosure_task mbt ON mbt.id=a.task_id LEFT JOIN mes_enclosure_process mbp ON mbp.id=a.process_id
a.product_type=#{productType} and team.organization_type=1
and a.factory_id=#{factoryId}
and a.team_id=#{teamId}
and team.production_line_id=#{productionLineId}
and a.workshop_id=#{workshopId}
