AND DATE(a.create_time)<=DATE(#{endDate})

SELECT report.id, report.create_time date, report.quantity, report.process_id, report.team_id, user.`name` user_name, leader.`name` leaderName, factory.`name` 'factory.name', workshop.`name` 'workshop.name', production_line.`name` 'production_line.name', process.`name` process_name FROM mes_enclosure_produce_team_report report LEFT JOIN mes_enclosure_task_process task_process ON report.task_process_id=task_process.id LEFT JOIN mes_enclosure_factory factory ON factory.id=task_process.factory_id LEFT JOIN mes_enclosure_workshop workshop ON workshop.id=task_process.workshop_id LEFT JOIN mes_enclosure_production_line production_line ON production_line.id=task_process.production_line_id LEFT JOIN mes_enclosure_process process ON process.id=report.process_id LEFT JOIN sys_user user ON user.id=report.user_id LEFT JOIN mes_enclosure_team_user_link team_user_link ON team_user_link.team_id=report.team_id AND team_user_link.bool_delete_enum=FALSE AND team_user_link.bool_leader_enum=TRUE LEFT JOIN sys_user leader ON leader.id=team_user_link.user_id
report.bool_delete_enum=FALSE AND report.product_id=#{id} AND report.product_type=#{prodcutType}
ORDER BY task_process.sequence

SELECT a.* FROM ( SELECT report.task_process_id id, report.create_time, report.number, product.serial_number, c.user_name teamLeaderName FROM `mes_enclosure_produce_team_report` report LEFT JOIN tech_artifact product ON report.product_id = product.id LEFT JOIN mes_enclosure_team_user_link c ON report.team_id = c.team_id AND c.bool_leader_enum = 1 AND c.bool_delete_enum = 0 WHERE task_process_id = #{previousTaskProcessId} AND report.bool_delete_enum = 0 AND report.inspection_quantity = report.quantity ) a LEFT JOIN ( SELECT report.task_process_id id, report.number FROM `mes_enclosure_produce_team_report` report WHERE task_process_id = #{taskProcessId} AND report.bool_delete_enum = 0)b ON a.number=b.number WHERE b.id IS NULL
AND a.number=#{number}
order by a.number

SELECT report.task_process_id id, report.create_time, report.number, product.serial_number, c.user_name teamLeaderName FROM `mes_enclosure_produce_team_report` report LEFT JOIN tech_artifact product ON report.product_id=product.id LEFT JOIN mes_enclosure_team_user_link c ON report.team_id = c.team_id AND c.bool_leader_enum = 1 AND c.bool_delete_enum = 0 WHERE task_process_id=#{taskProcessId}
AND number=#{number}
AND report.team_id=#{teamId}
AND report.bool_delete_enum = 0 AND report.inspection_quantity!=report.quantity AND report.number NOT IN ( SELECT b.number FROM mes_enclosure_qhse a LEFT JOIN mes_enclosure_qhse_inspection_link b ON a.id=b.qhse_id WHERE task_process_id=#{taskProcessId} AND a.bool_delete_enum=0 AND b.bool_delete_enum=0 AND b.number IS NOT NULL) order by report.number

