SELECT a.create_time, a.update_time, a.id, a.process_id 'process.id', a.product_id, a.task_type_enum, a.quantity, a.inspection_quantity, a.report_type, mba.serial_number serial_number, cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.id 'monomer.id', pm.`name` 'monomer.name', pd.id 'area.id', pd.`name` 'area.name', mbw.id 'workshop.id', mbw.`name` 'workshop.name', mbpl.id 'production_line.id', mbpl.`name` 'production_line.name', mbp.NAME 'process.name', su.id 'user.id', su.name 'user.name', gro.id 'groups.id', gro.name 'groups.name' FROM mes_enclosure_produce_team_report a LEFT JOIN mes_enclosure_task task ON a.task_id = task.id LEFT JOIN contract_project cp ON cp.id = task.project_id LEFT JOIN plan_monomer pm ON pm.id = task.monomer_id LEFT JOIN plan_area pd ON pd.id = task.plan_id LEFT JOIN mes_enclosure_factory mbf ON mbf.id = task.factory_id LEFT JOIN mes_enclosure_workshop mbw ON mbw.id = task.workshop_id LEFT JOIN mes_enclosure_production_line mbpl ON mbpl.id = task.production_line_id LEFT JOIN mes_enclosure_process mbp ON mbp.id = a.process_id LEFT JOIN mes_enclosure_groups gro ON gro.id = task.groups_id LEFT JOIN sys_user su ON a.user_id =su.id
