select.if:
SELECT `month`, SUM( mete ) mete FROM ( SELECT DATE_FORMAT( complete.create_time, "%Y-%m" ) `month`, complete.quantity * artifact.net_weight mete FROM mes_enclosure_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id WHERE complete.task_type_enum = 2
AND complete.project_id = #{projectId}
AND DATE_FORMAT(complete.create_time, "%Y" ) = DATE_FORMAT(#{dateTime}, "%Y")
) a GROUP BY `month`

mapper.select:
SELECT a.process_id 'process.id', a.process_name 'process.name', a.task_type_enum, a.workshop_id 'workshop.id', a.workshop_name 'workshop.name', a.groups_id 'groups.id', a.groups_name 'groups.name', a.team_id 'team.id', a.user_name 'team.name', IFNULL( SUM( a.inspection_quantity ), 0 ) inspection_quantity, IFNULL( SUM( a.net_weight ), 0 ) net_weight FROM ( SELECT process.id process_id, process.`name` process_name, process.product_type task_type_enum, workshop.id workshop_id, workshop.`name` workshop_name, gro.id groups_id, gro.`name` groups_name, report.team_id team_id, user_link.user_name user_name, report.inspection_quantity, CASE report.task_type_enum WHEN 1 THEN report.inspection_quantity * part.net_weight WHEN 2 THEN report.inspection_quantity * artifact.net_weight WHEN 16 THEN report.inspection_quantity * assemble.net_weight END net_weight FROM `mes_enclosure_produce_team_report` report LEFT JOIN tech_artifact artifact ON artifact.id = report.product_id LEFT JOIN tech_assemble assemble ON assemble.id = report.product_id LEFT JOIN tech_machine_part part ON part.id = report.product_id LEFT JOIN mes_enclosure_process process ON process.id = report.process_id LEFT JOIN mes_enclosure_groups gro ON gro.id = report.groups_id LEFT JOIN mes_enclosure_workshop workshop ON workshop.id = gro.workshop_id LEFT JOIN mes_enclosure_team_user_link user_link ON user_link.team_id = report.team_id AND user_link.bool_delete_enum = 0 AND user_link.bool_leader_enum = 1 WHERE report.bool_delete_enum = 0
AND report.process_id=#{processId}
AND gro.workshop_id=#{workshopId}
AND DATE(report.create_time)>=DATE(#{startDate})
AND DATE(report.create_time)<=DATE(#{endDate})
) a GROUP BY a.team_id, a.user_name, a.process_id, a.workshop_id, a.groups_id

SELECT rep.create_time, rep.id, rep.product_id, rep.quantity, enc.serial_number, enc.`name` 'productName', enc.length 'length', pro.id 'project.id' , pro.`name` 'project.name', pro.serial_number 'project.serialNumber', pro.short_name 'project.shortName', plan.id 'plan.id', plan.`name` 'plan.name', shop.id 'workshop.id', shop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', cess.id 'process.id', cess.`name` 'process.name', rep.user_id 'user.id', us.`name` 'user.name' FROM mes_enclosure_produce_team_report rep LEFT JOIN tech_enclosure enc ON rep.product_id =enc.id LEFT JOIN contract_project pro ON enc.project_id=pro.id LEFT JOIN enclosure_plan plan ON plan.id=enc.enclosure_plan_id LEFT JOIN mes_building_factory fac ON fac.id=rep.factory_id LEFT JOIN mes_building_workshop shop ON shop.id=rep.workshop_id LEFT JOIN mes_enclosure_production_line line ON line.id=rep.production_line_id LEFT JOIN mes_enclosure_process cess ON rep.process_id=cess.id LEFT JOIN sys_user us ON rep.user_id=us.id where rep.bool_delete_enum=0
and enc.serial_number like CONCAT('%', #{serialNumber},'%')
and enc.project_id=#{projectId}
AND enc.project_id IN
#{projectId}
AND rep.team_id IN
#{teamId}
AND date(rep.create_time) >= date(#{startDate})
AND date(rep.create_time) <= date(#{endDate})
ORDER BY rep.create_time DESC

SELECT rep.create_time, rep.id, rep.product_id, rep.quantity, enc.serial_number, enc.`name` 'productName', enc.length 'length', pro.id 'project.id' , pro.`name` 'project.name', pro.serial_number 'project.serialNumber', pro.short_name 'project.shortName', pm.id 'monomer.id', pm.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', shop.id 'workshop.id', shop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', cess.id 'process.id', cess.`name` 'process.name', rep.user_id 'user.id', us.`name` 'user.name' FROM mes_enclosure_produce_team_report rep LEFT JOIN tech_enclosure enc ON rep.product_id =enc.id LEFT JOIN contract_project pro ON enc.project_id=pro.id LEFT JOIN plan_monomer pm ON pm.id=enc.monomer_id LEFT JOIN plan_area area ON area.id=enc.area_id LEFT JOIN mes_building_factory fac ON fac.id=rep.factory_id LEFT JOIN mes_building_workshop shop ON shop.id=rep.workshop_id LEFT JOIN mes_enclosure_production_line line ON line.id=rep.production_line_id LEFT JOIN mes_enclosure_process cess ON rep.process_id=cess.id LEFT JOIN sys_user us ON rep.user_id=us.id where rep.bool_delete_enum=0
and enc.serial_number like CONCAT('%', #{serialNumber},'%')
and enc.project_id=#{projectId}
AND enc.project_id IN
#{projectId}
AND rep.team_id IN
#{teamId}
AND date(rep.create_time) >= date(#{startDate})
AND date(rep.create_time) <= date(#{endDate})
ORDER BY rep.create_time DESC

SELECT pro.id 'project.id', pro.NAME 'project.name', pro.serial_number 'project.serialNumber', pro.short_name 'project.shortName', plan.id 'plan.id', plan.NAME 'plan.name', SUM( rep.quantity ) 'reportQuantity', SUM( rep.quantity ) * enc.length 'reportTotalLength', rep.price, enc.id 'productId', enc.NAME, enc.material, enc.serial_number, enc.plate, enc.thickness, enc.quantity 'listQuantity', enc.length, enc.quantity * enc.length 'listTotalLength', enc.color, enc.category, enc.brand, enc.weight, enc.coating, enc.plating FROM mes_enclosure_produce_team_report rep LEFT JOIN tech_enclosure enc ON rep.product_id = enc.id LEFT JOIN contract_project pro ON pro.id = enc.project_id LEFT JOIN enclosure_plan plan ON enc.enclosure_plan_id=plan.id WHERE rep.bool_delete_enum=0
AND rep.price=#{price}
AND date(rep.create_time) >= date(#{startTime})
AND date(rep.create_time) <= date(#{endTime})
AND enc.project_id =#{projectId}
AND rep.team_id =#{teamId}
AND rep.production_line_id =#{lineId}
AND enc.project_id IN
#{projectId}
AND enc.category =#{category}
GROUP BY rep.product_id

SELECT enc.plate 'plate', IFNULL(SUM( rep.quantity * enc.length ) ,0) 'completeLength' FROM mes_enclosure_produce_team_report rep LEFT JOIN tech_enclosure enc ON rep.product_id = enc.id LEFT JOIN contract_project pro ON enc.project_id = pro.id WHERE rep.bool_delete_enum = 0
AND date(rep.create_time) >= date(#{startTime})
AND date(rep.create_time) <= date(#{endTime})
AND enc.project_id =#{projectId}
AND enc.category =#{category}
GROUP BY enc.plate
